class Customer {
  #id;                    // stable identity, never reassigned
  constructor(id, name) { this.#id = id; this.name = name; }
  get id() { return this.#id; }
  rename(name) { this.name = name; }        // state may change
  equals(other) { return other instanceof Customer && other.id === this.#id; }
}
// a === b is true only while a and b are the same object in memory
